-- More accurate campus places. Every building now lists each of its levels,
-- and each level offers the same few general areas (seminar rooms, group study
-- rooms, study areas, toilets, lifts, stairs & corridors, or offices), so any
-- spot on campus fits one option. The F&B outlets are named one by one from
-- SMU's store directory (October 2026), and the Level 1 security counter of
-- every building is a collection point, as SMU's lost and found rules say.
--
-- Existing rows keep their id, so the items and meetups that point at them are
-- untouched: a few are renamed in place (step 1), then the new rows are added
-- (step 2). Rows are found by building, floor and area, which are unique.
-- The same list is in server/data/campus-spots.json for the seed.

-- 1. Rename the old rows and set the collection points
update campus_spots set area = 'lobby & security counter', is_collection_point = true where building = 'SOE/SCIS 2' and floor = 'Level 1' and area = 'lobby';
update campus_spots set area = 'lobby & security counter', is_collection_point = true where building = 'SCIS 1' and floor = 'Level 1' and area = 'lobby';
update campus_spots set area = 'lifts, stairs & corridors' where building = 'SCIS 1' and floor = 'Level 2' and area = 'lift lobby';
update campus_spots set is_collection_point = false where building = 'Li Ka Shing Library' and floor = 'Level 2' and area = 'service desk';
update campus_spots set area = 'quiet study areas' where building = 'Li Ka Shing Library' and floor = 'Level 3' and area = 'quiet study area';
update campus_spots set area = 'lobby & security counter', is_collection_point = true where building = 'SOA' and floor = 'Level 1' and area = 'lobby';
update campus_spots set area = 'lobby & security counter' where building = 'Administration Building' and floor = 'Level 1' and area = 'lobby security counter';
update campus_spots set area = 'lobby & security counter', is_collection_point = true where building = 'SOSS/CIS' and floor = 'Level 1' and area = 'lobby';
update campus_spots set area = 'lobby & security counter', is_collection_point = true where building = 'YPHSL' and floor = 'Level 1' and area = 'lobby';
update campus_spots set is_collection_point = false where building = 'YPHSL' and floor = 'Basement 1' and area = 'Kwa Geok Choo Law Library';
update campus_spots set area = 'lobby & security counter', is_collection_point = true where building = 'SMU Connexion' and floor = 'Level 1' and area = 'lobby';

-- 2. Add the new rows (skipped if a row with the same name is already there)
on conflict (building, floor, area) do nothing;
